namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public string DepartmentAbbreviation { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, data structures, and the design of software and hardware systems." },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Exploration of abstract structures, quantities, and patterns through rigorous logical reasoning." },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Investigation of matter, energy, and the fundamental forces that govern the natural world." },
            new() { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Critical reading, analytical writing, and the study of literature across periods and cultures." },
            new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Examination of past events, societies, and civilizations to understand the forces that shaped the modern world." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, DepartmentName = "Computer Science", DepartmentAbbreviation = "CS", CourseNumber = "CS 101", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen specializes in programming language theory and CS education. She has published over 30 papers and received the university's Excellence in Teaching award.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentName = "Computer Science", DepartmentAbbreviation = "CS", CourseNumber = "CS 201", Title = "Data Structures & Algorithms", Description = "Design and analysis of fundamental data structures (lists, trees, graphs, hash tables) and algorithms (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. Brian Park", InstructorBio = "Dr. Park's research focuses on algorithm optimization and competitive programming. He is a former ACM-ICPC world finalist." },
            new() { Id = 3, DepartmentId = 1, DepartmentName = "Computer Science", DepartmentAbbreviation = "CS", CourseNumber = "CS 350", Title = "Operating Systems", Description = "Principles of operating system design including process management, memory management, file systems, and concurrency.", Credits = 4, Schedule = "Mon/Wed 1:00–2:30 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen specializes in programming language theory and CS education. She has published over 30 papers and received the university's Excellence in Teaching award." },

            // Mathematics
            new() { Id = 4, DepartmentId = 2, DepartmentName = "Mathematics", DepartmentAbbreviation = "MATH", CourseNumber = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Prof. Diana Ruiz", InstructorBio = "Prof. Ruiz is a specialist in mathematical analysis with 20 years of teaching experience. She authored the textbook 'Calculus: An Intuitive Approach'.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentName = "Mathematics", DepartmentAbbreviation = "MATH", CourseNumber = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, eigenvalues, and applications to data science and computer graphics.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Ethan Novak", InstructorBio = "Dr. Novak researches numerical linear algebra and its applications in machine learning." },

            // Physics
            new() { Id = 6, DepartmentId = 3, DepartmentName = "Physics", DepartmentAbbreviation = "PHYS", CourseNumber = "PHYS 110", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions. Calculus co-requisite.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM + Fri Lab 2:00–4:50 PM", InstructorName = "Dr. Fatima Al-Rashid", InstructorBio = "Dr. Al-Rashid is an experimental physicist whose research spans condensed matter and materials science.", IsFeatured = true },
            new() { Id = 7, DepartmentId = 3, DepartmentName = "Physics", DepartmentAbbreviation = "PHYS", CourseNumber = "PHYS 210", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Fatima Al-Rashid", InstructorBio = "Dr. Al-Rashid is an experimental physicist whose research spans condensed matter and materials science." },

            // English
            new() { Id = 8, DepartmentId = 4, DepartmentName = "English", DepartmentAbbreviation = "ENG", CourseNumber = "ENG 101", Title = "College Composition", Description = "Develop critical reading and academic writing skills. Emphasis on thesis-driven essays, research methods, and revision strategies.", Credits = 3, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", InstructorName = "Prof. Grace Okafor", InstructorBio = "Prof. Okafor is a published author and rhetoric scholar. She directs the university Writing Center." },
            new() { Id = 9, DepartmentId = 4, DepartmentName = "English", DepartmentAbbreviation = "ENG", CourseNumber = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, examining themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Henry Walsh", InstructorBio = "Dr. Walsh specializes in 20th-century American fiction and has published two books on the Harlem Renaissance.", IsFeatured = true },

            // History
            new() { Id = 10, DepartmentId = 5, DepartmentName = "History", DepartmentAbbreviation = "HIST", CourseNumber = "HIST 101", Title = "World History to 1500", Description = "A global survey of civilizations from antiquity through the late medieval period, covering political, cultural, and economic developments.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Irene Petrova", InstructorBio = "Dr. Petrova is an ancient and medieval historian with fieldwork experience across Europe and the Middle East." },
            new() { Id = 11, DepartmentId = 5, DepartmentName = "History", DepartmentAbbreviation = "HIST", CourseNumber = "HIST 205", Title = "Modern European History", Description = "Europe from the Enlightenment to the present: revolutions, industrialization, world wars, and the European Union.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", InstructorName = "Dr. James Liu", InstructorBio = "Dr. Liu focuses on diplomatic history and transatlantic relations. He previously served as a Fulbright scholar in Berlin." },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public (bool Success, string Message) SubmitEnrollment(EnrollmentRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.StudentName))
            return (false, "Student name is required.");

        if (string.IsNullOrWhiteSpace(request.StudentId))
            return (false, "Student ID is required.");

        var course = GetCourse(request.CourseId);
        if (course is null)
            return (false, "Please select a valid course.");

        return (true, $"Enrollment request submitted for {request.StudentName} (ID: {request.StudentId}) in {course.CourseNumber}: {course.Title}.");
    }
}

