toolArgs.file_text:
@page "/courses"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4 align-items-end">
    <div class="col-md-5">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Course name, number, or instructor..." />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select id="departmentId" name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Course</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.CourseNumber</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td>@course.Schedule</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p class="text-muted">Fill out the form below to submit an enrollment request.</p>

@if (resultMessage is not null)
{
    <div class="alert @(resultSuccess ? "alert-success" : "alert-danger")">
        @resultMessage
    </div>
}

<div class="row">
    <div class="col-lg-6">
        <form method="post" action="/enroll">
            <AntiforgeryToken />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required placeholder="e.g., S12345" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <select id="courseId" name="Model.CourseId" class="form-select" required>
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in CatalogService.GetCourses())
                    {
                        <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.CourseNumber — @course.Title (@course.Credits cr.)</option>
                    }
                </select>
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-link">Back to Catalog</a>
        </form>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private string? resultMessage;
    private bool resultSuccess;

    protected override void OnInitialized()
    {
        // Pre-select course from query string if navigated from a course detail page
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? "GET"))
        {
            var (success, message) = CatalogService.SubmitEnrollment(Model);
            resultSuccess = success;
            resultMessage = message;

            if (success)
            {
                Model = new();
            }
        }
    }

    [CascadingParameter]
    public HttpContext? HttpContextAccessor { get; set; }
}

